 public AdvisorPanel(Action<RepairPlan> launch,Action<bool> optimize){execute=launch;efficient=optimize;Dock=DockStyle.Fill;BackColor=bg;ForeColor=ink;var tabs=new TabControl{Dock=DockStyle.Fill};Controls.Add(tabs);TabPage diagnosis=Page(tabs,"Diagnose & repair"),ai=Page(tabs,"AI counselor"),tuning=Page(tabs,"Optimizations");
