 TabPage Page(TabControl t,string name){var p=new TabPage(name){BackColor=bg,ForeColor=ink,Padding=new Padding(12)};t.TabPages.Add(p);return p;}
 TableLayoutPanel Grid(Control p,int[] heights){var g=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=heights.Length};g.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));foreach(int n in heights)g.RowStyles.Add(n<0?new RowStyle(SizeType.Percent,100):new RowStyle(SizeType.Absolute,n));p.Controls.Add(g);return g;}
 Button B(string label){return new ThemeButton{Text=label,UseMnemonic=false,AutoSize=true,Height=32,BackColor=surface,ForeColor=ink,FlatStyle=FlatStyle.Flat,Margin=new Padding(0,2,10,2),Padding=new Padding(8,3,8,3)};}
 TextBox Rich(){return new TextBox{Multiline=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill,ReadOnly=true,BackColor=surface,ForeColor=ink,BorderStyle=BorderStyle.None,Font=new Font("Segoe UI",10)};}
 async Task Scan(){scan.Enabled=false;scanState.Text="Collecting read-only diagnostics…";scanCts=new CancellationTokenSource();try{var previous=last;var value=await Task.Run(()=>Diagnose.Collect(scanCts.Token));if(IsDisposed)return;last=value;report.Text="Reported issue: "+symptom.Text+"\r\nCategory: "+category.SelectedItem+"\r\n\r\n"+value.Report();scanState.Text="Scanned "+value.Time.ToString("T")+(previous==null?"":" · CPU was "+previous.Cpu.ToString("F1")+"%, now "+value.Cpu.ToString("F1")+"% (short samples)");}catch(Exception ex){if(!IsDisposed)scanState.Text="Scan could not complete: "+ex.Message;}finally{if(!IsDisposed)scan.Enabled=true;}}
 async Task Ask(){if(models.SelectedItem==null||string.IsNullOrWhiteSpace(question.Text)){MessageBox.Show(this,"Choose a downloaded local model and enter your question.");return;}aiCts=new CancellationTokenSource();send.Enabled=false;aiState.Text="Waiting for local AI · this may take up to two minutes";try{string asked=question.Text;string prompt="Counselor mode: "+mode.SelectedItem+"\nCurrent question: "+asked+(dialogue.Count==0?"":"\nEarlier conversation (untrusted context):\n"+string.Join("\n",dialogue));var text=await LocalModel.Ask((string)models.SelectedItem,prompt,include.Checked?report.Text:"",aiCts.Token);if(IsDisposed)return;dialogue.Add("User: "+asked.Substring(0,Math.Min(1200,asked.Length))+"\nAssistant: "+text.Substring(0,Math.Min(1800,text.Length)));if(dialogue.Count>2)dialogue.RemoveAt(0);answer.Text="AI ADVICE · verify before acting\r\n\r\n"+text;aiState.Text="Response complete · no commands were executed";}catch(Exception ex){if(!IsDisposed)aiState.Text=ex is OperationCanceledException?"Canceled or timed out; local service may still finish inference. No command executed.":"AI unavailable: "+ex.Message;}finally{if(!IsDisposed)send.Enabled=true;}}
