 void Export(){using(var d=new System.Windows.Forms.SaveFileDialog{Filter="Text report|*.txt",FileName="Aster-diagnosis-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".txt"})if(d.ShowDialog(this)==DialogResult.OK){try{File.WriteAllText(d.FileName,report.Text,Encoding.UTF8);}catch(Exception ex){MessageBox.Show(this,ex.Message);}}}
 protected override void Dispose(bool disposing){if(disposing){if(scanCts!=null)scanCts.Cancel();if(aiCts!=null)aiCts.Cancel();}base.Dispose(disposing);}
