static class AuraProfile {
 public static string PathName{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Pulse","Aura.xml");}}
 public static void Eco(){EcoAt(PathName);}
 public static void EcoAt(string p){Directory.CreateDirectory(Path.GetDirectoryName(p));XDocument doc;if(File.Exists(p)){using(var r=XmlReader.Create(p,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null}))doc=XDocument.Load(r);File.Copy(p,p+".before-eco",true);}else{doc=new XDocument(new XElement("Settings"));doc.Save(p+".before-eco");}foreach(var pair in new[]{new[]{"Fps","15"},new[]{"Density","40"},new[]{"Volume","0"},new[]{"PauseBattery","true"},new[]{"PauseFullscreen","true"}})doc.Root.SetElementValue(pair[0],pair[1]);Write(doc,p);}
 public static void Undo(){UndoAt(PathName);}
 public static void UndoAt(string p){if(!File.Exists(p+".before-eco"))throw new Exception("No saved pre-Eco settings were found.");XDocument doc;using(var r=XmlReader.Create(p+".before-eco",new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null}))doc=XDocument.Load(r);Write(doc,p);}
 static void Write(XDocument doc,string p){string temp=p+".profile.tmp";doc.Save(temp);if(File.Exists(p))File.Replace(temp,p,null);else File.Move(temp,p);}
}
